<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { management, type ChatMessage, type MutedStudent } from '../api/management';
import { actor } from '../auth';
import { dateTime, label } from '../lib/format';
import { newClientId } from '../lib/id';
import { ApiError } from '../api/http';
const props=defineProps<{assignmentId:string;problemId:string;enabled:boolean}>();
const manager=computed(()=>actor.value?.role!=='STUDENT');
const messages=ref<ChatMessage[]>([]),text=ref(''),error=ref(''),sending=ref(false),muted=ref(false),listOpen=ref(false),muteList=ref<MutedStudent[]>([]),listLoading=ref(false),listError=ref(''),moderating=ref(false),body=ref<HTMLElement>();
const failedAvatars=ref(new Set<string>());
function authorAvatar(message:ChatMessage){
  const url=message.authorAvatarUrl;
  if(!url||failedAvatars.value.has(url))return undefined;
  const path=`/api/assignments/${encodeURIComponent(props.assignmentId)}/problems/${encodeURIComponent(props.problemId)}/chat/participants/${encodeURIComponent(message.authorId)}/avatar`;
  if(url===path)return url;
  return url.startsWith(`${path}?v=`)&&/^[a-zA-Z0-9._~%:+-]+$/.test(url.slice(path.length+3))?url:undefined;
}
function avatarFailed(message:ChatMessage){if(message.authorAvatarUrl)failedAvatars.value.add(message.authorAvatarUrl);}
const authorInitial=(name:string)=>Array.from(name.trim())[0]||'同';
let timer:ReturnType<typeof setTimeout>|undefined;let destroyed=false;let key='',lastText='';let loading=false;
async function load(){if(loading||destroyed)return;loading=true;let retry=true;try{const stay=!body.value||body.value.scrollHeight-body.value.scrollTop-body.value.clientHeight<70;const result=await management.messages(props.assignmentId,props.problemId);if(destroyed)return;messages.value=result.items;muted.value=result.muted;error.value='';if(stay){await nextTick();if(body.value)body.value.scrollTop=body.value.scrollHeight;}}catch(e){if(!destroyed){error.value=(e as Error).message;if(e instanceof ApiError&&[401,403,404].includes(e.status))retry=false;}}finally{loading=false;if(!destroyed&&retry){clearTimeout(timer);timer=setTimeout(load,3000);}}}
async function send(){const value=text.value.trim();if(!value||sending.value||muted.value||!props.enabled)return;sending.value=true;error.value='';try{if(value!==lastText||!key){key=newClientId();lastText=value;}await management.sendMessage(props.assignmentId,props.problemId,value,key);text.value='';key='';await load();await nextTick();if(body.value)body.value.scrollTop=body.value.scrollHeight;}catch(e){error.value=(e as Error).message;}finally{sending.value=false;}}
async function loadMutes(){listLoading.value=true;listError.value='';try{muteList.value=await management.mutedStudents(props.assignmentId);}catch(e){listError.value=(e as Error).message;}finally{listLoading.value=false;}}
async function mute(message:ChatMessage){try{await ElMessageBox.confirm(`禁止 ${message.authorName} 在本作业中发言？`,'禁言学生',{confirmButtonText:'禁言',cancelButtonText:'取消'});moderating.value=true;await management.muteStudent(props.assignmentId,message.authorId);ElMessage.success('已禁言');if(listOpen.value)await loadMutes();}catch(e){if(e instanceof Error)ElMessage.error(e.message);}finally{moderating.value=false;}}
async function unmute(row:MutedStudent){moderating.value=true;try{await management.unmuteStudent(props.assignmentId,row.studentId);await loadMutes();ElMessage.success('已解除禁言');}catch(e){ElMessage.error((e as Error).message);}finally{moderating.value=false;}}
async function retract(message:ChatMessage){try{await ElMessageBox.confirm('撤回这条消息？','撤回消息',{confirmButtonText:'撤回',cancelButtonText:'取消'});moderating.value=true;await management.retractMessage(props.assignmentId,props.problemId,message.id);await load();}catch(e){if(e instanceof Error)ElMessage.error(e.message);}finally{moderating.value=false;}}
onMounted(load);onBeforeUnmount(()=>{destroyed=true;clearTimeout(timer);});
</script>
<template><aside class="panel chat-panel" aria-label="题目聊天室"><header class="chat-heading"><h2>题目讨论</h2><el-button v-if="manager" link type="primary" @click="listOpen=true;loadMutes()">被禁言列表</el-button></header><p v-if="!enabled" class="chat-notice">该作业未开放聊天</p><div ref="body" class="chat-messages" aria-live="polite" aria-relevant="additions text"><p v-if="!messages.length&&!error" class="chat-empty">暂无消息</p><article v-for="message in messages" :key="message.id" class="chat-message" :class="{own:message.authorId===actor?.id}"><span class="chat-avatar" aria-hidden="true"><img v-if="authorAvatar(message)" :src="authorAvatar(message)" alt="" width="32" height="32" loading="lazy" decoding="async" @error="avatarFailed(message)"/><template v-else>{{authorInitial(message.authorName)}}</template></span><div class="chat-message-content"><div class="chat-author"><strong>{{message.authorName}}</strong><small v-if="message.role!=='STUDENT'">{{label(message.role)}}</small><time>{{dateTime(message.createdAt)}}</time></div><p class="chat-message-body" :class="{retracted:message.retracted}">{{message.retracted?'消息已撤回':message.body}}</p><div v-if="manager" class="message-actions"><el-button v-if="!message.retracted" link :disabled="moderating" @click="retract(message)">撤回</el-button><el-button v-if="message.role==='STUDENT'" link :disabled="moderating" @click="mute(message)">禁言</el-button></div></div></article></div><div v-if="error" class="chat-error" role="alert">{{error}} <el-button link @click="load">重试</el-button></div><footer class="chat-composer"><p v-if="muted" class="chat-notice">你在本作业中已被禁言</p><el-input v-model="text" type="textarea" :rows="3" resize="none" maxlength="1000" :disabled="sending||muted||!enabled" placeholder="与同学交流解题思路" aria-label="讨论消息"/><div><small>{{[...text].length}} / 1000</small><el-button type="primary" size="small" :loading="sending" :disabled="!text.trim()||muted||!enabled" @click="send">发送</el-button></div></footer><el-dialog v-if="manager" v-model="listOpen" title="被禁言列表" width="600px" append-to-body><el-alert v-if="listError" :title="listError" type="error" :closable="false"/><p class="muted">禁言范围：当前作业的所有题目聊天室。</p><el-table v-loading="listLoading" :data="muteList" empty-text="暂无被禁言的学生"><el-table-column prop="name" label="姓名"/><el-table-column prop="studentNumber" label="学号"/><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" :disabled="moderating" @click="unmute(row)">解除禁言</el-button></template></el-table-column></el-table></el-dialog></aside></template>
<style scoped>.chat-panel{padding:0;min-width:0;position:sticky;top:16px;overflow:hidden}.chat-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:16px;border-bottom:1px solid #e8eef1}.chat-heading h2{font-size:15px;margin:0}.chat-heading .el-button{font-size:11px}.chat-messages{height:460px;max-height:60vh;overflow:auto;padding:16px;scrollbar-width:thin}.chat-empty{text-align:center;color:#8e9ba4;font-size:12px;padding-top:60px}.chat-message{display:flex;align-items:flex-start;gap:8px;margin-bottom:18px}.chat-avatar{display:grid;place-items:center;flex:0 0 32px;width:32px;height:32px;border-radius:50%;overflow:hidden;background:#e8eff2;color:#527481;font-size:12px}.chat-avatar img{display:block;width:32px;height:32px;object-fit:cover}.chat-message-content{flex:1;min-width:0}.own .chat-avatar{background:#dcefed;color:#287d7b}.chat-author{display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:11px;color:#788b98}.chat-author strong{font-weight:500;color:#486271}.chat-author small{color:#168d91}.chat-author time{font-size:9px;margin-left:auto}.chat-message-body{background:#f3f6f8;padding:10px 12px;border-radius:7px;margin:6px 0 0;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.7}.own .chat-message-body{background:#eaf5f4}.chat-message-body.retracted{background:none;color:#8d99a4;font-size:11px;padding:5px 0}.message-actions{display:flex;gap:12px;justify-content:flex-end}.message-actions .el-button{font-size:10px;padding:3px 0}.chat-composer{padding:14px;border-top:1px solid #e8eef1}.chat-composer>div:last-child{display:flex;justify-content:space-between;align-items:center;margin-top:10px}.chat-composer small{font-size:10px;color:#8a99a4}.chat-notice{font-size:11px;color:#a47436;margin:10px 14px}.chat-error{font-size:11px;color:#b44e48;padding:8px 14px}@media(max-width:1150px){.chat-panel{position:static}.chat-messages{height:330px}}
</style>
